fn create_row(n: u8) -> Vec<u8> {
    (0..n).collect() // Create a range from 0 to n-1 and collect it into a Vec<u8>
}

fn indices(n: u8) -> Vec<Vec<u8>> {
    vec![create_row(n)] // Return a vector containing the row generated by create_row
}

// Example usage
fn main() {
    let n = 5;
    let row = create_row(n);
    let grid = indices(n);
    
    println!("{:?}", row); // Output: [0, 1, 2, 3, 4]
    println!("{:?}", grid); // Output: [[0, 1, 2, 3, 4]]
}